    20→package org.apache.druid.jackson;
    21→
    22→import com.fasterxml.jackson.core.JsonFactory;
    23→import com.fasterxml.jackson.databind.DeserializationFeature;
    24→import com.fasterxml.jackson.databind.MapperFeature;
    25→import com.fasterxml.jackson.databind.ObjectMapper;
    26→import com.fasterxml.jackson.databind.SerializationFeature;
    27→import com.fasterxml.jackson.datatype.guava.GuavaModule;
    28→
    29→/**
    30→ */
    31→public class DefaultObjectMapper extends ObjectMapper
    32→{
    33→  public DefaultObjectMapper()
    34→  {
    35→    this((JsonFactory) null);
    36→  }
    37→
    38→  public DefaultObjectMapper(DefaultObjectMapper mapper)
    39→  {
    40→    super(mapper);
    41→  }
    42→
    43→  public DefaultObjectMapper(JsonFactory factory)
    44→  {
    45→    super(factory);
    46→    registerModule(new DruidDefaultSerializersModule());
    47→    registerModule(new GuavaModule());
    48→    registerModule(new GranularityModule());
    49→    registerModule(new AggregatorsModule());
    50→    registerModule(new StringComparatorModule());
    51→    registerModule(new SegmentizerModule());
    52→
    53→    configure(DeserializationFeature.FAIL_ON_UNKNOWN_PROPERTIES, false);
    54→    configure(MapperFeature.AUTO_DETECT_GETTERS, false);
    55→    // See https://github.com/FasterXML/jackson-databind/issues/170
    56→    // configure(MapperFeature.AUTO_DETECT_CREATORS, false);
    57→    configure(MapperFeature.AUTO_DETECT_FIELDS, false);
    58→    configure(MapperFeature.AUTO_DETECT_IS_GETTERS, false);
    59→    configure(MapperFeature.AUTO_DETECT_SETTERS, false);
    60→    configure(MapperFeature.ALLOW_FINAL_FIELDS_AS_MUTATORS, false);
    61→    configure(SerializationFeature.INDENT_OUTPUT, false);
    62→    configure(SerializationFeature.FLUSH_AFTER_WRITE_VALUE, false);
    63→  }
    64→
    65→  @Override
    66→  public ObjectMapper copy()
    67→  {
    68→    return new DefaultObjectMapper(this);
    69→  }
    70→}
