    20→package org.apache.druid.indexing.overlord.setup;
    21→
    22→import com.fasterxml.jackson.annotation.JacksonInject;
    23→import com.fasterxml.jackson.annotation.JsonCreator;
    24→import com.fasterxml.jackson.annotation.JsonProperty;
    25→import com.google.common.base.Preconditions;
    26→import com.google.common.collect.ImmutableMap;
    27→import org.apache.druid.indexing.common.task.Task;
    28→import org.apache.druid.indexing.overlord.ImmutableWorkerInfo;
    29→import org.apache.druid.indexing.overlord.config.WorkerTaskRunnerConfig;
    30→import org.apache.druid.js.JavaScriptConfig;
    31→
    32→import javax.script.Compilable;
    33→import javax.script.Invocable;
    34→import javax.script.ScriptEngine;
    35→import javax.script.ScriptEngineManager;
    36→import javax.script.ScriptException;
    37→
    38→public class JavaScriptWorkerSelectStrategy implements WorkerSelectStrategy
    39→{
    40→  public interface SelectorFunction
    41→  {
    42→    String apply(WorkerTaskRunnerConfig config, ImmutableMap<String, ImmutableWorkerInfo> zkWorkers, Task task);
    43→  }
    44→
    45→  private final String function;
    46→
    47→  // This variable is lazily initialized to avoid unnecessary JavaScript compilation during JSON serde
    48→  private SelectorFunction fnSelector;
    49→
    50→  @JsonCreator
    51→  public JavaScriptWorkerSelectStrategy(
    52→      @JsonProperty("function") String fn,
    53→      @JacksonInject JavaScriptConfig config
    54→  )
    55→  {
    56→    Preconditions.checkNotNull(fn, "function must not be null");
    57→    Preconditions.checkState(config.isEnabled(), "JavaScript is disabled");
    58→
    59→    this.function = fn;
    60→  }
    61→
    62→  private SelectorFunction compileSelectorFunction()
    63→  {
    64→    final ScriptEngine engine = new ScriptEngineManager().getEngineByName("javascript");
    65→    try {
    66→      ((Compilable) engine).compile("var apply = " + function).eval();
    67→      return ((Invocable) engine).getInterface(SelectorFunction.class);
    68→    }
    69→    catch (ScriptException e) {
    70→      throw new RuntimeException(e);
    71→    }
    72→  }
    73→
    74→  @Override
    75→  public ImmutableWorkerInfo findWorkerForTask(
    76→      WorkerTaskRunnerConfig config,
    77→      ImmutableMap<String, ImmutableWorkerInfo> zkWorkers,
    78→      Task task
    79→  )
    80→  {
    81→    fnSelector = fnSelector == null ? compileSelectorFunction() : fnSelector;
    82→    String worker = fnSelector.apply(config, zkWorkers, task);
    83→    return worker == null ? null : zkWorkers.get(worker);
    84→  }
    85→
    86→  @JsonProperty
    87→  public String getFunction()
    88→  {
    89→    return function;
    90→  }
    91→
    92→  @Override
    93→  public boolean equals(Object o)
    94→  {
    95→    if (this == o) {
    96→      return true;
    97→    }
    98→    if (o == null || getClass() != o.getClass()) {
    99→      return false;
   100→    }
   101→
   102→    JavaScriptWorkerSelectStrategy that = (JavaScriptWorkerSelectStrategy) o;
   103→
   104→    if (function != null ? !function.equals(that.function) : that.function != null) {
   105→      return false;
   106→    }
   107→
   108→    return true;
   109→  }
   110→
   111→  @Override
   112→  public int hashCode()
   113→  {
   114→    return function.hashCode();
   115→  }
   116→
   117→  @Override
   118→  public String toString()
   119→  {
   120→    return "JavaScriptWorkerSelectStrategy{" +
   121→           "function='" + function + '\'' +
   122→           '}';
   123→  }
   124→}
