    37→public class DruidSecondaryModule implements Module
    38→{
    39→  private final Properties properties;
    40→  private final ConfigurationObjectFactory factory;
    41→  private final ObjectMapper jsonMapper;
    42→  private final ObjectMapper smileMapper;
    43→  private final Validator validator;
    44→
    45→  @Inject
    46→  public DruidSecondaryModule(
    47→      Properties properties,
    48→      ConfigurationObjectFactory factory,
    49→      @Json ObjectMapper jsonMapper,
    50→      @Smile ObjectMapper smileMapper,
    51→      Validator validator
    52→  )
    53→  {
    54→    this.properties = properties;
    55→    this.factory = factory;
    56→    this.jsonMapper = jsonMapper;
    57→    this.smileMapper = smileMapper;
    58→    this.validator = validator;
    59→  }
    60→
    61→  @Override
    62→  public void configure(Binder binder)
    63→  {
    64→    binder.install(new DruidGuiceExtensions());
    65→    binder.bind(Properties.class).toInstance(properties);
    66→    binder.bind(ConfigurationObjectFactory.class).toInstance(factory);
    67→    binder.bind(ObjectMapper.class).to(Key.get(ObjectMapper.class, Json.class));
    68→    binder.bind(Validator.class).toInstance(validator);
    69→    binder.bind(JsonConfigurator.class);
    70→  }
    71→
    72→  @Provides @LazySingleton @Json
    73→  public ObjectMapper getJsonMapper(final Injector injector)
    74→  {
    75→    setupJackson(injector, jsonMapper);
    76→    return jsonMapper;
    77→  }
